customCSS:
.t, .history { color: #6e6a86; }
.join { color: #95b1ac; }
.part, .quit { color: #6e6a86; }
.kick, .error { color: #eb6f92; }
.notice { color: #f6c177; }
.action { color: #c4a7e7; }
.mode, .nick, .topic, .server { color: #9ccfd8; }
.highlight { color: #e0def4; background-color: #403d52; border-left: 3px solid #c4a7e7; padding-left: 8px; }
.reply { color: #6e6a86; border-left: 2px solid #31748f; padding-left: 6px; }
.oper { color: #191724; background-color: #f6c177; }
.reactions { color: #31748f; background-color: #1f1d2e; }
.card { background-color: #1f1d2e; border-color: #6e6a86; }
.card-title { color: #31748f; }
.card-desc { color: #6e6a86; }
.daychange { color: #6e6a86; border-color: #1f1d2e; }
